import type { Metadata, Viewport } from "next";
import "./globals.css";

export const metadata: Metadata = {
  title: "AionUi",
  description: "Transform your command-line AI · Modern & Efficient",
  applicationName: "AionUi",
  icons: {
    icon: "/seo/icon-192.png",
    apple: "/seo/icon-180.png",
  },
};

export const viewport: Viewport = {
  themeColor: "#4E5969",
  width: "device-width",
  initialScale: 1,
};

// Restore theme synchronously to prevent a flash (mirrors AionUi's bootstrap).
const themeBootstrap = `(function(){try{var t=localStorage.getItem('__aionui_theme');if(!t){t='dark';}document.documentElement.classList.toggle('dark',t!=='light');document.documentElement.setAttribute('data-theme',t);}catch(e){document.documentElement.classList.add('dark');}})();`;

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en" suppressHydrationWarning className="h-full">
      <head>
        <script dangerouslySetInnerHTML={{ __html: themeBootstrap }} />
      </head>
      <body className="min-h-full bg-bg-1 text-fg antialiased">{children}</body>
    </html>
  );
}
